    /**
     * Tests getting all TenantUsers.
     *
     * @return    Collection
     */
    public List<TenantUser> testGetAll() throws Throwable {
    LOGGER.info( "TenantUserTest:testGetAll() - Retrieving Collection of TenantUsers:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all TenantUser : " );
    List<TenantUser> collection  = null;

    try {
        // call the static get method on the TenantUserService
        collection = service.getAllTenantUser();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            TenantUser currEntity  = null;
            Iterator<TenantUser> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getTenantUserId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

